async function duration(file) {
  const { stdout } = await execFileAsync3("ffprobe", [
    "-v",
    "error",
    "-show_entries",
    "format=duration",
    "-of",
    "default=nw=1:nk=1",
    file
  ]);
  const value = Number(stdout.trim());
  if (!Number.isFinite(value) || value <= 0) throw new Error(`Invalid generated video: ${path.basename(file)}.`);
  return value;
}
async function finishAudio(source, output, silent, narrationPath, nativeAudioPresent) {
  if (silent) {
    await execFileAsync3("ffmpeg", [
      "-y",
      "-hide_banner",
      "-loglevel",
      "error",
      "-i",
      source,
      "-map",
      "0:v:0",
      "-c:v",
      "copy",
      "-an",
      "-movflags",
      "+faststart",
      output
    ], { timeout: 10 * 6e4, maxBuffer: 8 * 1024 * 1024 });
    return;
  }
  if (narrationPath) {
    const [videoSeconds, narrationSeconds] = await Promise.all([
      duration(source),
      duration(narrationPath).catch(() => 0)
    ]);
    const extendSeconds = narrationSeconds > videoSeconds + 0.25 ? narrationSeconds - videoSeconds : 0;
    const videoLabel = extendSeconds > 0 ? "[v]" : "0:v:0";
    const targetSeconds = Math.max(videoSeconds, narrationSeconds).toFixed(2);
    const filters = [
      ...extendSeconds > 0 ? [`[0:v]tpad=stop_mode=clone:stop_duration=${extendSeconds.toFixed(2)}[v]`] : [],
      nativeAudioPresent ? `[0:a]volume=0.32,apad=whole_dur=${targetSeconds}[bed];[1:a]volume=1.0,apad=whole_dur=${targetSeconds}[voice];[bed][voice]amix=inputs=2:duration=first:dropout_transition=2[a]` : `[1:a]volume=1.0,apad=whole_dur=${targetSeconds}[a]`
    ];
    await execFileAsync3("ffmpeg", [
      "-y",
      "-hide_banner",
      "-loglevel",
      "error",
      "-i",
      source,
      "-i",
      narrationPath,
      "-filter_complex",
      filters.join(";"),
      "-map",
      videoLabel,
      "-map",
      "[a]",
      "-c:v",
      extendSeconds > 0 ? "libx264" : "copy",
      ...extendSeconds > 0 ? ["-preset", "fast", "-crf", "18", "-pix_fmt", "yuv420p"] : [],
      "-c:a",
      "aac",
      "-b:a",
      "192k",
      "-ar",
      "48000",
      "-shortest",
      "-movflags",
      "+faststart",
      output
    ], { timeout: 10 * 6e4, maxBuffer: 8 * 1024 * 1024 });
    if (extendSeconds > 0) {
      console.info(`[ai-video] narration ${narrationSeconds.toFixed(1)}s exceeded assembled video ${videoSeconds.toFixed(1)}s \u2014 held final frame for ${extendSeconds.toFixed(1)}s instead of cutting narration`);
    }
    return;
  }
  await fs.copyFile(source, output);
}
