    "-f",
    "lavfi",
    "-i",
    `aevalsrc=${expression}|${expression}:s=48000:d=${seconds.toFixed(3)}`,
    "-af",
    `lowpass=f=4200,highpass=f=90,afade=t=in:st=0:d=0.8,afade=t=out:st=${Math.max(0, seconds - 1.2).toFixed(3)}:d=1.2`,
    "-c:a",
    "aac",
    "-b:a",
    "192k",
    output
